    if (@offsetOf(GpuVulkanOptions, "feature_list") != @offsetOf(c.SDL_GPUVulkanOptions, "feature_list")) @compileError("ABI field mismatch for GpuVulkanOptions.feature_list");
    if (@offsetOf(GpuVulkanOptions, "vulkan10_physical_device_features") != @offsetOf(c.SDL_GPUVulkanOptions, "vulkan_10_physical_device_features")) @compileError("ABI field mismatch for GpuVulkanOptions.vulkan10_physical_device_features");
