/// SDL type `Uint32`.
pub const InitFlags = packed struct(u32) {
    /// Unknown or currently unused bits preserved during integer round trips.
    reserved_0: u4 = 0,
    /// `InitFlags.audio` implies `InitFlags.events`
    audio: bool = false,
    /// `InitFlags.video` implies `InitFlags.events`, should be initialized on the main thread
    video: bool = false,
    /// Unknown or currently unused bits preserved during integer round trips.
    reserved_1: u3 = 0,
    /// `InitFlags.joystick` implies `InitFlags.events`
    joystick: bool = false,
    /// Unknown or currently unused bits preserved during integer round trips.
    reserved_2: u2 = 0,
    /// Flag bit `InitFlags.haptic`.
    haptic: bool = false,
    /// `InitFlags.gamepad` implies `InitFlags.joystick`
    gamepad: bool = false,
    /// Flag bit `InitFlags.events`.
    events: bool = false,
    /// `InitFlags.sensor` implies `InitFlags.events`
    sensor: bool = false,
    /// `InitFlags.camera` implies `InitFlags.events`
    camera: bool = false,
    /// Unknown or currently unused bits preserved during integer round trips.
    reserved_3: u15 = 0,

    /// Preserve every known and unknown flag bit.
    pub inline fn fromInt(value: u32) @This() {
        return @bitCast(value);
    }

    /// Convert this flag set to its integer representation.
    pub inline fn toInt(self: @This()) u32 {
        return @bitCast(self);
    }
};

