/// - **See also:** tray.insertEntryAt
const TrayEntryFlags = u32;

/// The flags on a window.
///
/// These cover a lot of true/false, or on/off, window state. Some of it is immutable after being set through video.createWindow(), some of it can be changed on existing windows by the app, and some of it might be altered by the user or system outside of the app's control.
/// When creating windows with `video.WindowFlags.resizable`, SDL will constrain resizable windows to the dimensions recommended by the compositor to fit it within the usable desktop space, although some compositors will do this automatically without intervention as well. Use `video.Window.setResizable` after creation instead if you wish to create a window with a specific size.
///
/// - **Since:** This datatype is available since SDL 3.2.0.
/// - **See also:** video.Window.getFlags
const WindowFlags = packed struct(u64) {
    /// window is in fullscreen mode
    fullscreen: bool = false,
    /// window usable with OpenGL context
    open_gl: bool = false,
    /// window is occluded
    occluded: bool = false,
    /// window is neither mapped onto the desktop nor shown in the taskbar/dock/window list; video.Window.show() is required for it to become visible
    hidden: bool = false,
    /// no window decoration
    borderless: bool = false,
    /// window can be resized
    resizable: bool = false,
    /// window is minimized
    minimized: bool = false,
    /// window is maximized
    maximized: bool = false,
    /// window has grabbed mouse input
    mouse_grabbed: bool = false,
    /// window has input focus
    input_focus: bool = false,
    /// window has mouse focus
    mouse_focus: bool = false,
    /// window not created by SDL
    external: bool = false,
    /// window is modal
    modal: bool = false,
    /// window uses high pixel density back buffer if possible
    high_pixel_density: bool = false,
    /// window has mouse captured (unrelated to MOUSE_GRABBED)
    mouse_capture: bool = false,
    /// window has relative mode enabled
    mouse_relative_mode: bool = false,
    /// window should always be above others
    always_on_top: bool = false,
    /// window should be treated as a utility window, not showing in the task bar and window list
    utility: bool = false,
    /// window should be treated as a tooltip and does not get mouse or keyboard focus, requires a parent window
    tooltip: bool = false,
    /// window should be treated as a popup menu, requires a parent window
    popup_menu: bool = false,
    /// window has grabbed keyboard input
    keyboard_grabbed: bool = false,
    /// window is in fill-document mode (Emscripten only), since SDL 3.4.0
    fill_document: bool = false,
    /// Unknown or currently unused bits preserved during integer round trips.
    reserved_0: u6 = 0,
    /// window usable for Vulkan surface
    vulkan: bool = false,
    /// window usable for Metal view
    metal: bool = false,
    /// window with transparent buffer
    transparent: bool = false,
    /// window should not be focusable
    not_focusable: bool = false,
    /// Unknown or currently unused bits preserved during integer round trips.
    reserved_1: u32 = 0,

    /// Preserve every known and unknown flag bit.
    pub inline fn fromInt(value: u64) @This() {
        return @bitCast(value);
    }

    /// Convert this flag set to its integer representation.
    pub inline fn toInt(self: @This()) u64 {
        return @bitCast(self);
    }

    /// Composite flag value `SDL_WINDOW_SURFACE_VSYNC_DISABLED`.
    pub const surface_vsync_disabled: @This() = fromInt(@intCast(c.SDL_WINDOW_SURFACE_VSYNC_DISABLED));
};

