/// - **See also:** mutex.Condition.wait
/// - **See also:** mutex.Condition.waitTimeout
inline fn broadcastCondition(cond: ?Condition) void {
    c.SDL_BroadcastCondition(if (cond) |resource| @ptrCast(resource.value) else null);
