/// - **Since:** This function is available since SDL 3.2.0.
inline fn calculateGpuTextureFormatSize(format: GpuTextureFormat, width: u32, height: u32, depth_or_layer_count: u32) u32 {
    return c.SDL_CalculateGPUTextureFormatSize(@intCast(@intFromEnum(format)), width, height, depth_or_layer_count);
}

/// SDL operation `stdinc.calloc`.
inline fn calloc(nmemb: c_ulong, size: c_ulong) ?*anyopaque {
