inline fn getDisplays(allocator_: std.mem.Allocator) Error![]DisplayId {
    const Count = @typeInfo(@typeInfo(@TypeOf(c.SDL_GetDisplays)).@"fn".params[0].type.?).pointer.child;
    var count: Count = 0;
    const result = c.SDL_GetDisplays(&count);
    if (result == null) return error.SdlFailure;
    defer c.SDL_free(@ptrCast(result));
    const length = std.math.cast(usize, count) orelse return error.SdlFailure;
    const copy = allocator_.alloc(DisplayId, length) catch return error.OutOfMemory;
    errdefer allocator_.free(copy);
    @memcpy(copy, result[0..length]);
    return copy;
}

/// Named output values.
const GetDisplayUsableBoundsResult = struct {
    /// Output `rect`.
    rect: Rect,
};

/// Get the usable desktop area represented by a display, in screen coordinates.
///
/// This is the same area as video.getDisplayBounds() reports, but with portions reserved by the system removed. For example, on Apple's macOS, this subtracts the area occupied by the menu bar and dock.
/// Setting a window to be fullscreen generally bypasses these unusable areas, so these are good guidelines for the maximum space available to a non-fullscreen window.
///
/// - **Parameters:**
///   - `display_id`: the instance ID of the display to query.
///
/// - **Returns:** true on success or false on failure; call error_.get() for more information.
/// - **Thread safety:** This function should only be called on the main thread.
/// - **Since:** This function is available since SDL 3.2.0.
/// - **See also:** video.getDisplayBounds
/// - **See also:** video.getDisplays
/// Returns named output values.
inline fn getDisplayUsableBounds(display_id: DisplayId) Error!GetDisplayUsableBoundsResult {
    var rect_raw: @typeInfo(@typeInfo(@TypeOf(c.SDL_GetDisplayUsableBounds)).@"fn".params[1].type.?).pointer.child = undefined;
    if (!c.SDL_GetDisplayUsableBounds(display_id, &rect_raw)) return error.SdlFailure;
    return GetDisplayUsableBoundsResult{
        .rect = @bitCast(rect_raw),
    };
}

/// Get the value of a variable in the environment.
///
/// The name of the variable is case sensitive on all platforms.
/// This function uses SDL's cached copy of the environment and is thread-safe.
///
/// - **Parameters:**
///   - `name`: the name of the variable to get.
///
/// - **Returns:** a pointer to the value of the variable or NULL if it can't be found.
/// - **Thread safety:** It is safe to call this function from any thread.
/// - **Since:** This function is available since SDL 3.2.0.
inline fn getenv(name: ?[:0]const u8) ?[:0]const u8 {
    const result = c.SDL_getenv(if (name != null) @ptrCast(name.?.ptr) else null);
    return if (result == null) null else std.mem.span(@as([*:0]const u8, @ptrCast(result.?)));
}

/// Get the value of a variable in the environment.
///
/// This function bypasses SDL's cached copy of the environment and is not thread-safe.
/// On some platforms, this may make case-insensitive matches, while other platforms are case-sensitive. It is best to be precise with strings used for queries through this interface. stdinc.getenv is always case-sensitive, however.
///
/// - **Parameters:**
///   - `name`: the name of the variable to get.
///
/// - **Returns:** a pointer to the value of the variable or NULL if it can't be found.
/// - **Thread safety:** This function is not thread safe, consider using stdinc.getenv() instead.
/// - **Since:** This function is available since SDL 3.2.0.
/// - **See also:** stdinc.getenv
inline fn getenvUnsafe(name: ?[:0]const u8) ?[:0]const u8 {
    const result = c.SDL_getenv_unsafe(if (name != null) @ptrCast(name.?.ptr) else null);
    return if (result == null) null else std.mem.span(@as([*:0]const u8, @ptrCast(result.?)));
}

/// Get the process environment.
///
/// This is initialized at application start and is not affected by setenv() and unsetenv() calls after that point. Use stdinc.Environment.setVariable() and stdinc.Environment.unsetVariable() if you want to modify this environment, or stdinc.setenvUnsafe() or stdinc.unsetenvUnsafe() if you want changes to persist in the C runtime environment after quit().
///
/// - **Returns:** a pointer to the environment for the process or NULL on failure; call error_.get() for more information.
/// - **Thread safety:** It is safe to call this function from any thread.
/// - **Since:** This function is available since SDL 3.2.0.
/// - **See also:** stdinc.Environment.getVariable
/// - **See also:** stdinc.getEnvironmentVariables
/// - **See also:** stdinc.Environment.setVariable
/// - **See also:** stdinc.Environment.unsetVariable
///
/// Returns `error.SdlFailure` when SDL reports failure.
inline fn getEnvironment() Error!Environment {
    const result = c.SDL_GetEnvironment();
    if (result == null) return error.SdlFailure;
    return Environment{ .value = @ptrCast(result.?) };
}

/// Get the value of a variable in the environment.
///
/// - **Parameters:**
///   - `env`: the environment to query.
///   - `name`: the name of the variable to get.
///
/// - **Returns:** a pointer to the value of the variable or NULL if it can't be found.
/// - **Thread safety:** It is safe to call this function from any thread.
/// - **Since:** This function is available since SDL 3.2.0.
/// - **See also:** stdinc.getEnvironment
/// - **See also:** stdinc.createEnvironment
/// - **See also:** stdinc.getEnvironmentVariables
/// - **See also:** stdinc.Environment.setVariable
/// - **See also:** stdinc.Environment.unsetVariable
inline fn getEnvironmentVariable(env: ?Environment, name: ?[:0]const u8) ?[:0]const u8 {
    const result = c.SDL_GetEnvironmentVariable(if (env) |resource| @ptrCast(resource.value) else null, if (name != null) @ptrCast(name.?.ptr) else null);
    return if (result == null) null else std.mem.span(@as([*:0]const u8, @ptrCast(result.?)));
}

/// Get all variables in the environment.
///
/// - **Parameters:**
///   - `env`: the environment to query.
///
/// - **Returns:** a NULL terminated array of pointers to environment variables in the form "variable=value" or NULL on failure; call error_.get() for more information. The returned collection owns allocator-backed copies of every string; call `deinit` when finished.
/// - **Thread safety:** It is safe to call this function from any thread.
/// - **Since:** This function is available since SDL 3.2.0.
/// - **See also:** stdinc.getEnvironment
/// - **See also:** stdinc.createEnvironment
/// - **See also:** stdinc.getEnvironmentVariables
/// - **See also:** stdinc.Environment.setVariable
/// - **See also:** stdinc.Environment.unsetVariable
inline fn getEnvironmentVariables(allocator_: std.mem.Allocator, env: ?Environment) Error!OwnedStrings {
    const result = c.SDL_GetEnvironmentVariables(if (env) |resource| @ptrCast(resource.value) else null);
    if (result == null) return error.SdlFailure;
    defer c.SDL_free(@ptrCast(result));
    var length: usize = 0;
    while (result[length] != null) : (length += 1) {}
    const items = allocator_.alloc([:0]u8, length) catch return error.OutOfMemory;
    var initialized: usize = 0;
    errdefer {
        for (items[0..initialized]) |item| allocator_.free(item);
        allocator_.free(items);
    }
    for (items, 0..) |*item, index| {
        const source = result[index];
        if (source == null) return error.SdlFailure;
        item.* = support.copyOwnedZString(allocator_, @ptrCast(source)) catch return error.OutOfMemory;
        initialized += 1;
    }
    return .{ .allocator = allocator_, .items = items };
}

/// Retrieve a message about the last error that occurred on the current thread.
///
/// It is possible for multiple errors to occur before calling error_.get(). Only the last error is returned.
/// The message is only applicable when an SDL function has signaled an error. You must check the return values of SDL function calls to determine when to appropriately call error_.get(). You should *not* use the results of error_.get() to decide if an error has occurred! Sometimes SDL will set an error string even when reporting success.
/// SDL will *not* clear the error string for successful API calls. You *must* check return values for failure cases before you can assume the error string applies.
/// Error strings are set per-thread, so an error set in a different thread will not interfere with the current thread's operation.
/// The returned value is a thread-local string which will remain valid until the current thread's error string is changed. The caller should make a copy if the value is needed after the next SDL API call.
///
/// - **Returns:** a message with information about the specific error that occurred, or an empty string if there hasn't been an error message set since the last call to error_.clear().
/// - **Thread safety:** It is safe to call this function from any thread.
/// - **Since:** This function is available since SDL 3.2.0.
/// - **See also:** error_.clear
/// - **See also:** error_.set
inline fn getError() ?[:0]const u8 {
    const result = c.SDL_GetError();
    return if (result == null) null else std.mem.span(@as([*:0]const u8, @ptrCast(result.?)));
}

/// Generate an English description of an event.
///
/// This will fill `buf` with a null-terminated string that might look something like this:
/// ```c
/// SDL_EVENT_MOUSE_MOTION(timestamp=1140256324windowid=2which=0state=0x=492.99y=139.09xrel=52yrel=6)
/// ```
///
/// The exact format of the string is not guaranteed; it is intended for logging purposes, to be read by a human, and not parsed by a computer.
/// The returned value follows the same rules as stdinc.snprintf(): `buf` will always be NULL-terminated (unless `buflen` is zero), and will be truncated if `buflen` is too small. The return code is the number of bytes needed for the complete string, not counting the NULL-terminator, whether the string was truncated or not. Unlike stdinc.snprintf(), though, this function never returns -1.
///
/// - **Parameters:**
///   - `event`: an event to describe. May be NULL.
///   - `buf`: the buffer to fill with the description string. May be NULL.
///
/// - **Returns:** number of bytes needed for the full string, not counting the null-terminator byte.
/// - **Thread safety:** It is safe to call this function from any thread.
/// - **Since:** This function is available since SDL 3.4.0.
inline fn getEventDescription(event: ?*const Event, buf: []u8) c_int {
    return c.SDL_GetEventDescription(@ptrCast(event), @ptrCast(buf.ptr), @intCast(buf.len));
}

/// Named output values.
const GetEventFilterResult = struct {
    /// Output `filter`.
    filter: EventFilter,
    /// Output `userdata`.
    userdata: ?*anyopaque,
};

/// Query the current event filter.
///
/// This function can be used to "chain" filters, by saving the existing filter before replacing it with a function that will call that saved filter.
///
/// - **Returns:** true on success or false if there is no event filter set.
/// - **Thread safety:** It is safe to call this function from any thread.
/// - **Since:** This function is available since SDL 3.2.0.
/// - **See also:** events.setEventFilter
/// Returns named output values.
inline fn getEventFilter() ?GetEventFilterResult {
    var filter_raw: @typeInfo(@typeInfo(@TypeOf(c.SDL_GetEventFilter)).@"fn".params[0].type.?).pointer.child = undefined;
    var userdata_raw: @typeInfo(@typeInfo(@TypeOf(c.SDL_GetEventFilter)).@"fn".params[1].type.?).pointer.child = undefined;
    if (!c.SDL_GetEventFilter(&filter_raw, &userdata_raw)) return null;
    return GetEventFilterResult{
        .filter = if (filter_raw == null) null else @ptrCast(filter_raw),
        .userdata = if (userdata_raw == null) null else @ptrCast(userdata_raw),
    };
}

/// Get a floating point property from a group of properties.
///
/// You can use properties.getPropertyType() to query whether the property exists and is a floating point property.
///
/// - **Parameters:**
///   - `props`: the properties to query.
///   - `name`: the name of the property to query.
///   - `default_value`: the default value of the property.
///
/// - **Returns:** the value of the property, or `default_value` if it is not set or not a float property.
/// - **Thread safety:** It is safe to call this function from any thread.
/// - **Since:** This function is available since SDL 3.2.0.
/// - **See also:** properties.getPropertyType
/// - **See also:** properties.hasProperty
/// - **See also:** properties.setFloatProperty
inline fn getFloatProperty(props: PropertiesId, name: ?[:0]const u8, default_value: f32) f32 {
    return c.SDL_GetFloatProperty(props, if (name != null) @ptrCast(name.?.ptr) else null, default_value);
}

/// Get a list of fullscreen display modes available on a display.
///
/// The display modes are sorted in this priority:
/// - w -> largest to smallest
/// - h -> largest to smallest
/// - bits per pixel -> more colors to fewer colors
/// - packed pixel layout -> largest to smallest
/// - refresh rate -> highest to lowest
/// - pixel density -> lowest to highest
///
/// - **Parameters:**
///   - `display_id`: the instance ID of the display to query.
///
/// - **Returns:** a NULL terminated array of display mode pointers or NULL on failure; call error_.get() for more information. The returned slice is allocated with the caller-provided allocator.
/// - **Thread safety:** This function should only be called on the main thread.
/// - **Since:** This function is available since SDL 3.2.0.
/// - **See also:** video.getDisplays
inline fn getFullscreenDisplayModes(allocator_: std.mem.Allocator, display_id: DisplayId) Error![]DisplayMode {
    const Count = @typeInfo(@typeInfo(@TypeOf(c.SDL_GetFullscreenDisplayModes)).@"fn".params[1].type.?).pointer.child;
    var count: Count = 0;
    const result = c.SDL_GetFullscreenDisplayModes(display_id, &count);
    if (result == null) return error.SdlFailure;
    defer c.SDL_free(@ptrCast(result));
    const length = std.math.cast(usize, count) orelse return error.SdlFailure;
    const copy = allocator_.alloc(DisplayMode, length) catch return error.OutOfMemory;
    errdefer allocator_.free(copy);
    for (copy, 0..) |*item, index| {
        const source = result[index];
        if (source == null) return error.SdlFailure;
        item.* = @bitCast(source.*);
    }
    return copy;
}

