    var percent_raw: @typeInfo(@typeInfo(@TypeOf(c.SDL_GetGamepadPowerInfo)).@"fn".params[1].type.?).pointer.child = undefined;
    const value_raw = c.SDL_GetGamepadPowerInfo(if (gamepad_2) |resource| @ptrCast(resource.value) else null, &percent_raw);
    return GetGamepadPowerInfoResult{
        .value = @enumFromInt(value_raw),
        .percent = percent_raw,
    };
}

