}

/// Get a list of currently connected haptic devices.
///
/// - **Returns:** a 0 terminated array of haptic device instance IDs or NULL on failure; call error_.get() for more information. The returned slice is allocated with the caller-provided allocator.
/// - **Since:** This function is available since SDL 3.2.0.
/// - **See also:** haptic.open
inline fn getHaptics(allocator_: std.mem.Allocator) Error![]HapticId {
    const Count = @typeInfo(@typeInfo(@TypeOf(c.SDL_GetHaptics)).@"fn".params[0].type.?).pointer.child;
    var count: Count = 0;
    const result = c.SDL_GetHaptics(&count);
    if (result == null) return error.SdlFailure;
    defer c.SDL_free(@ptrCast(result));
    const length = std.math.cast(usize, count) orelse return error.SdlFailure;
    const copy = allocator_.alloc(HapticId, length) catch return error.OutOfMemory;
    errdefer allocator_.free(copy);
    @memcpy(copy, result[0..length]);
    return copy;
}

