///
/// Returns `error.SdlFailure` when SDL reports failure.
inline fn getJoystickBall(joystick_2: ?Joystick, ball: c_int, dx: ?*c_int, dy: ?*c_int) Error!void {
    if (!c.SDL_GetJoystickBall(if (joystick_2) |resource| @ptrCast(resource.value) else null, ball, @ptrCast(dx), @ptrCast(dy))) return error.SdlFailure;
}

