    var b_raw: @typeInfo(@typeInfo(@TypeOf(c.SDL_GetRGBA)).@"fn".params[5].type.?).pointer.child = undefined;
    var a_raw: @typeInfo(@typeInfo(@TypeOf(c.SDL_GetRGBA)).@"fn".params[6].type.?).pointer.child = undefined;
    c.SDL_GetRGBA(pixelvalue, @ptrCast(format), @ptrCast(palette), &r_raw, &g_raw, &b_raw, &a_raw);
