    var scale_mode_raw: @typeInfo(@typeInfo(@TypeOf(c.SDL_GetTextureScaleMode)).@"fn".params[1].type.?).pointer.child = undefined;
    if (!c.SDL_GetTextureScaleMode(@ptrCast(texture), &scale_mode_raw)) return error.SdlFailure;
    return GetTextureScaleModeResult{
        .scale_mode = @enumFromInt(scale_mode_raw),
    };
}

/// Named output values.
const GetTextureSizeResult = struct {
    /// Output `w`.
    w: f32,
    /// Output `h`.
    h: f32,
};

/// Get the size of a texture, as floating point values.
///
/// - **Parameters:**
///   - `texture`: the texture to query.
///
/// - **Returns:** true on success or false on failure; call error_.get() for more information.
/// - **Thread safety:** This function should only be called on the main thread.
/// - **Since:** This function is available since SDL 3.2.0.
/// Returns named output values.
inline fn getTextureSize(texture: ?*Texture) Error!GetTextureSizeResult {
    var w_raw: @typeInfo(@typeInfo(@TypeOf(c.SDL_GetTextureSize)).@"fn".params[1].type.?).pointer.child = undefined;
    var h_raw: @typeInfo(@typeInfo(@TypeOf(c.SDL_GetTextureSize)).@"fn".params[2].type.?).pointer.child = undefined;
    if (!c.SDL_GetTextureSize(@ptrCast(texture), &w_raw, &h_raw)) return error.SdlFailure;
    return GetTextureSizeResult{
