inline fn getTrayMenuParentTray(menu: ?*TrayMenu) ?Tray {
    const result = c.SDL_GetTrayMenuParentTray(@ptrCast(menu));
    return if (result) |value| Tray{ .value = @ptrCast(value) } else null;
