/// - **See also:** tray.insertEntryAt
/// - **See also:** tray.createSubmenu
inline fn getTraySubmenu(entry: ?*TrayEntry) ?*TrayMenu {
    const result = c.SDL_GetTraySubmenu(@ptrCast(entry));
    return if (result == null) null else @ptrCast(result);
