}

/// Get a list of valid windows.
///
/// - **Returns:** a NULL terminated array of video.Window pointers or NULL on failure; call error_.get() for more information. The returned slice is allocated with the caller-provided allocator. Its handles are borrowed and must not be destroyed through the returned values.
/// - **Thread safety:** This function should only be called on the main thread.
/// - **Since:** This function is available since SDL 3.2.0.
inline fn getWindows(allocator_: std.mem.Allocator) Error![]Window {
    const Count = @typeInfo(@typeInfo(@TypeOf(c.SDL_GetWindows)).@"fn".params[0].type.?).pointer.child;
    var count: Count = 0;
    const result = c.SDL_GetWindows(&count);
    if (result == null) return error.SdlFailure;
    defer c.SDL_free(@ptrCast(result));
    const length = std.math.cast(usize, count) orelse return error.SdlFailure;
    const copy = allocator_.alloc(Window, length) catch return error.OutOfMemory;
    errdefer allocator_.free(copy);
    for (copy, 0..) |*item, index| {
        const source = result[index];
        if (source == null) return error.SdlFailure;
        item.* = .{ .value = @ptrCast(source) };
    }
    return copy;
}

