inline fn hidGetInputReport(dev: ?HidDevice, data: []u8) Error!c_int {
    const result = c.SDL_hid_get_input_report(if (dev) |resource| @ptrCast(resource.value) else null, @ptrCast(data.ptr), @intCast(data.len));
