/// - **See also:** pixels.mapRgba
/// - **See also:** surface.mapRgb
inline fn mapRgb(format: ?*const PixelFormatDetails, palette: ?*const Palette, r: u8, g: u8, b: u8) u32 {
    return c.SDL_MapRGB(@ptrCast(format), @ptrCast(palette), r, g, b);
}

