    if (!c.SDL_RenderTexture9GridTiled(if (renderer) |resource| @ptrCast(resource.value) else null, @ptrCast(texture), @ptrCast(srcrect), left_width, right_width, top_height, bottom_height, scale, @ptrCast(dstrect), tile_scale)) return error.SdlFailure;
