/// - **See also:** tray.insertEntryAt
/// - **See also:** tray.getEntryLabel
inline fn setTrayEntryLabel(entry: ?*TrayEntry, label: ?[:0]const u8) void {
    c.SDL_SetTrayEntryLabel(@ptrCast(entry), if (label != null) @ptrCast(label.?.ptr) else null);
}

