inline fn setWindowIcon(window: ?Window, icon: ?*Surface) Error!void {
    if (!c.SDL_SetWindowIcon(if (window) |resource| @ptrCast(resource.value) else null, @ptrCast(icon))) return error.SdlFailure;
}

/// Set a window's keyboard grab mode.
