inline fn setWindowKeyboardGrab(window: ?Window, grabbed: bool) Error!void {
    if (!c.SDL_SetWindowKeyboardGrab(if (window) |resource| @ptrCast(resource.value) else null, grabbed)) return error.SdlFailure;
}

